  solution: "#include <iostream>\nint main() {\n  int lives = 0;\n  int hits = 0;\n  std::cin >> lives >> hits;\n  if (hits < 0) hits = 0;\n  if (hits > lives) lives = 0;\n  else lives -= hits;\n  std::cout << \"lives \" << lives << \"\\n\";\n  if (lives == 0) std::cout << \"over\\n\";\n  return 0;\n}\n",
