      solution: "#include <iostream>\nint main() {\n  int x = 0;\n  std::cin >> x;\n  if (x < 0) x += 1;\n  std::cout << x << \"\\n\";\n  return 0;\n}\n",
      hints: ["Only negative values move.", "Zero is already clear of the wall."],
      tests: [{"stdin": "-3\n", "expected": "-2\n"}, {"stdin": "0\n", "expected": "0\n"}, {"stdin": "2\n", "expected": "2\n"}, {"stdin": "", "expected": "0\n"}],
